 320: /// Write `value` to `path` whole: a temp file beside it, synced, then
 321: /// renamed over it.
 322: pub fn write_document(path: &Path, value: &impl Serialize) -> io::Result<()> {
 323:     let mut temp = path.as_os_str().to_owned();
 324:     temp.push(TEMP_SUFFIX);
 325:     let temp = PathBuf::from(temp);
 326:     let result = (|| {
 327:         let mut file = File::create(&temp)?;
 328:         serde_json::to_writer_pretty(&mut file, value)?;
 329:         file.write_all(b"\n")?;
 330:         file.sync_all()?;
 331:         drop(file);
 332:         fs::rename(&temp, path)
 333:     })();
 334:     if result.is_err() {
 335:         let _ = fs::remove_file(&temp);
 336:     }
