 369: impl RunStore {
 370:     pub fn new(dir: impl Into<PathBuf>) -> Self {
 371:         Self { dir: dir.into() }
 372:     }
 373: 
 374:     pub fn dir(&self) -> &Path {
 375:         &self.dir
 376:     }
