 382:     /// Record a run starting: its spec, written once, and its record,
 383:     /// `running`, under the run's lock, held until the returned
 384:     /// [`LiveRun`] drops.
 385:     pub fn begin(&self, spec: &JobSpec, record: &RunRecord) -> io::Result<LiveRun> {
 386:         if !crate::job_log::valid_id(&record.run_id) {
 387:             return Err(io::Error::new(
 388:                 io::ErrorKind::InvalidInput,
 389:                 format!("{:?} cannot name a run", record.run_id),
 390:             ));
 391:         }
 392:         fs::create_dir_all(&self.dir)?;
 393:         let lock_path = self.path(&record.run_id, LOCK_SUFFIX);
 394:         let lock = open_lock(&lock_path)?;
 395:         lock.try_lock().map_err(|error| match error {
 396:             fs::TryLockError::WouldBlock => io::Error::new(
 397:                 io::ErrorKind::AlreadyExists,
 398:                 format!("run {} is already going", record.run_id),
 399:             ),
 400:             fs::TryLockError::Error(error) => error,
 401:         })?;
 402:         let live = LiveRun {
 403:             _lock: lock,
 404:             lock_path,
 405:         };
 406:         write_document(&self.path(&record.run_id, SPEC_SUFFIX), spec)?;
 407:         write_document(&self.path(&record.run_id, RECORD_SUFFIX), record)?;
 408:         Ok(live)
 409:     }
 410: 
 411:     /// Replace a run's record.
 412:     pub fn update(&self, record: &RunRecord) -> io::Result<()> {
 413:         write_document(&self.path(&record.run_id, RECORD_SUFFIX), record)
 414:     }
