 416:     /// A run's spec and record.
 417:     pub fn load(&self, run_id: &str) -> io::Result<(JobSpec, RunRecord)> {
 418:         if !crate::job_log::valid_id(run_id) {
 419:             return Err(io::Error::new(
 420:                 io::ErrorKind::InvalidInput,
 421:                 format!("{run_id:?} is not a job ID"),
 422:             ));
 423:         }
 424:         let spec = read_spec(&fs::read(self.path(run_id, SPEC_SUFFIX))?)?;
 425:         let record = self.settled(read_record(&fs::read(self.path(run_id, RECORD_SUFFIX))?)?);
 426:         Ok((spec, record))
 427:     }
