 429:     /// `record` as it stands: a `running` record whose command has died
 430:     /// (its lock is free) becomes `interrupted`, on disk too.
 431:     fn settled(&self, mut record: RunRecord) -> RunRecord {
 432:         if record.state != RunState::Running {
 433:             return record;
 434:         }
 435:         let lock_path = self.path(&record.run_id, LOCK_SUFFIX);
 436:         let Ok(lock) = open_lock(&lock_path) else {
 437:             return record;
 438:         };
 439:         if lock.try_lock().is_err() {
 440:             // Its command is going.
 441:             return record;
 442:         }
 443:         // Re-read under the lock: the command may have finished between.
 444:         if let Ok(now) =
 445:             fs::read(self.path(&record.run_id, RECORD_SUFFIX)).and_then(|bytes| read_record(&bytes))
 446:         {
 447:             record = now;
 448:         }
 449:         if record.state == RunState::Running {
 450:             record.state = RunState::Interrupted;
 451:             record.outcome.get_or_insert(Outcome::Interrupted);
 452:             record
 453:                 .detail
 454:                 .get_or_insert_with(|| "its command stopped before the run ended".into());
 455:             if let Err(error) = self.update(&record) {
 456:                 log::warn!(
 457:                     "job records: could not mark run {} interrupted: {error}",
 458:                     record.run_id
 459:                 );
 460:             }
 461:         }
 462:         drop(lock);
 463:         let _ = fs::remove_file(&lock_path);
 464:         record
 465:     }
