 467:     /// Every run in the store, newest first, each settled (see
 468:     /// [`load`](Self::load)). A record this build cannot read is skipped
 469:     /// with a warning; a missing folder holds none.
 470:     pub fn list(&self) -> io::Result<Vec<StoredRun>> {
 471:         let entries = match fs::read_dir(&self.dir) {
 472:             Ok(entries) => entries,
 473:             Err(error) if error.kind() == io::ErrorKind::NotFound => return Ok(Vec::new()),
 474:             Err(error) => return Err(error),
 475:         };
 476:         let mut runs = Vec::new();
 477:         for entry in entries.flatten() {
 478:             let name = entry.file_name();
 479:             let Some(run_id) = name.to_str().and_then(|n| n.strip_suffix(RECORD_SUFFIX)) else {
 480:                 continue;
 481:             };
 482:             if !crate::job_log::valid_id(run_id) {
 483:                 continue;
 484:             }
 485:             let record = match fs::read(entry.path()).and_then(|bytes| read_record(&bytes)) {
 486:                 Ok(record) => record,
 487:                 Err(error) => {
 488:                     log::warn!("job records: skipping {}: {error}", entry.path().display());
 489:                     continue;
 490:                 }
 491:             };
 492:             runs.push(StoredRun {
 493:                 spec_path: self.path(run_id, SPEC_SUFFIX),
 494:                 record_path: entry.path(),
 495:                 record: self.settled(record),
 496:             });
 497:         }
 498:         runs.sort_by(|a, b| {
 499:             b.record
 500:                 .started_ms
 501:                 .cmp(&a.record.started_ms)
 502:                 .then_with(|| b.record.run_id.cmp(&a.record.run_id))
 503:         });
 504:         Ok(runs)
 505:     }
