 507:     /// Remove the oldest runs beyond the newest `keep`, never one running
 508:     /// or waiting on a daemon; returns the runs removed. Holds the folder's
 509:     /// prune lock throughout, so two runs finishing at once do not race.
 510:     pub fn prune(&self, keep: usize) -> io::Result<Vec<String>> {
 511:         let lock = match open_lock(&self.dir.join(PRUNE_LOCK)) {
 512:             Ok(lock) => lock,
 513:             Err(error) if error.kind() == io::ErrorKind::NotFound => return Ok(Vec::new()),
 514:             Err(error) => return Err(error),
 515:         };
 516:         lock.lock()?;
 517:         let mut removed = Vec::new();
 518:         for run in self.list()?.into_iter().skip(keep) {
 519:             if matches!(
 520:                 run.record.state,
 521:                 RunState::Running | RunState::Waiting { .. }
 522:             ) {
 523:                 continue;
 524:             }
 525:             let run_id = &run.record.run_id;
 526:             match fs::remove_file(&run.record_path) {
 527:                 Ok(()) => {
 528:                     let _ = fs::remove_file(&run.spec_path);
 529:                     removed.push(run_id.clone());
 530:                 }
 531:                 Err(error) => {
 532:                     log::warn!("job records: could not prune run {run_id}: {error}")
 533:                 }
 534:             }
 535:         }
 536:         Ok(removed)
 537:     }
 538: }
