 410: /// One job's line in `blit jobs list` (no host): its ID, when it started,
 411: /// what it did, and where it is or how it ended.
 412: fn local_row(record: &RunRecord) -> String {
 413:     let started = i64::try_from(record.started_ms)
 414:         .ok()
 415:         .and_then(chrono::DateTime::from_timestamp_millis)
 416:         .map(|time| {
 417:             time.with_timezone(&chrono::Local)
 418:                 .format("%Y-%m-%d %H:%M:%S")
 419:                 .to_string()
 420:         })
 421:         .unwrap_or_else(|| "-".into());
 422:     let mut status = match &record.state {
 423:         RunState::Running => "running".to_string(),
 424:         RunState::Waiting { daemon, job_id } => format!("waiting on {daemon} (job {job_id})"),
 425:         RunState::Interrupted | RunState::Finished => record
 426:             .outcome
 427:             .map_or(record.state.as_str(), Outcome::as_str)
 428:             .to_string(),
 429:     };
 430:     if !matches!(record.state, RunState::Running | RunState::Waiting { .. }) {
 431:         if let Some(detail) = &record.detail {
 432:             status.push_str(&format!(": {detail}"));
 433:         }
 434:     }
 435:     if record.state == RunState::Finished {
 436:         status.push_str(&format!(
 437:             " ({} copied, {} deleted, {} failed)",
 438:             record.files_copied, record.files_deleted, record.files_failed
 439:         ));
 440:     }
 441:     format!(
 442:         "{}  {started}  {}  {} -> {}  {status}",
 443:         record.run_id, record.verb, record.source, record.destination
 444:     )
 445: }
