 459: /// Map [`CancelJobOutcome`] to the contract's exit codes.
 460: /// Pulled out as a sync helper so unit tests can pin the
 461: /// mapping without spinning up a tonic server.
 462: pub(crate) fn cancel_exit_code(outcome: &CancelJobOutcome) -> ExitCode {
 463:     match outcome {
 464:         CancelJobOutcome::Cancelled { .. } => ExitCode::SUCCESS,
 465:         CancelJobOutcome::NotFound { .. } => ExitCode::from(1),
 466:         CancelJobOutcome::Unsupported { .. } => ExitCode::from(2),
 467:     }
 468: }
