 374:         RunState::Waiting { .. } => None,
 375:         _ => Some(outcome),
 376:     };
 377:     record.detail = detail;
 378:     record.source_removed = source_removed;
 379:     if let Some(totals) = totals {
 380:         record.files_copied = totals.files_copied;
 381:         record.files_deleted = totals.files_deleted;
 382:         record.files_failed = totals.files_failed;
 383:         record.bytes_copied = totals.bytes_copied;
