 385:             .failures
 386:             .iter()
 387:             .map(|(path, reason)| (path.as_str(), reason.as_str()))
 388:             .collect();
 389:         let mut names: Vec<&str> = totals.failed_paths.iter().map(String::as_str).collect();
 390:         for (path, _) in &totals.failures {
 391:             if !names.contains(&path.as_str()) {
 392:                 names.push(path);
