 420: /// The run's job: what to run again. An error, in words, when the command
 421: /// line cannot be kept exactly (a folder or list name that is not UTF-8, an
 422: /// unreadable `--files-from` list — the command reports those itself).
 423: fn job_spec(verb: &str, args: &TransferArgs, machine: &str) -> Result<JobSpec, String> {
 424:     let cwd = std::env::current_dir().map_err(|error| format!("the current folder: {error}"))?;
 425:     let cwd_text = cwd
 426:         .to_str()
 427:         .ok_or("the current folder's name is not UTF-8")?
 428:         .to_string();
 429:     let endpoint = |text: &str| -> Result<SpecEndpoint, String> {
 430:         match parse_transfer_endpoint(text).map_err(|error| format!("{error:#}"))? {
 431:             Endpoint::Remote(remote) => {
 432:                 let (module, path) = match &remote.path {
 433:                     RemotePath::Module { module, rel_path } => (
 434:                         Some(module.clone()),
 435:                         rel_path.to_string_lossy().into_owned(),
 436:                     ),
 437:                     RemotePath::Root { rel_path } => {
 438:                         (None, rel_path.to_string_lossy().into_owned())
 439:                     }
 440:                     RemotePath::Discovery => (None, String::new()),
 441:                 };
 442:                 Ok(SpecEndpoint::Remote {
 443:                     locator: text.to_string(),
 444:                     host: remote.host.clone(),
 445:                     port: remote.port,
 446:                     module,
 447:                     path,
 448:                 })
 449:             }
 450:             Endpoint::Local(_) => job_record::absolute_local(&cwd, text)
 451:                 .map(|path| SpecEndpoint::Local { path })
 452:                 .ok_or_else(|| format!("{text}: its full name is not UTF-8")),
 453:         }
 454:     };
 455:     let files_from = match &args.files_from {
 456:         Some(list) => {
 457:             let text = std::fs::read_to_string(cwd.join(list))
 458:                 .map_err(|error| format!("{}: {error}", list.display()))?;
 459:             Some(text.lines().map(str::to_string).collect())
 460:         }
 461:         None => None,
 462:     };
 463:     Ok(JobSpec::new(
 464:         machine,
 465:         verb,
 466:         cwd_text,
 467:         endpoint(&args.source)?,
 468:         endpoint(&args.destination)?,
 469:         spec_options(args),
 470:         files_from,
 471:     ))
 472: }
