 128: /// What `blit jobs log` prints above a log's text.
 129: struct Heading {
 130:     role: String,
 131:     participant: String,
 132:     attempt: u32,
 133:     /// Why the log may not be finished, when it is not.
 134:     unfinished: Option<&'static str>,
 135: }
 136: 
 137: impl Heading {
 138:     fn from_daemon(header: &JobLogHeader) -> Self {
 139:         Self {
 140:             role: header.role.clone(),
 141:             participant: header.participant.clone(),
 142:             attempt: header.attempt,
 143:             unfinished: (!header.finished)
 144:                 .then_some("the job is running, or the daemon stopped during it"),
 145:         }
 146:     }
 147: 
 148:     fn from_disk(role: Role, participant: &str, attempt: u32, finished: bool) -> Self {
 149:         Self {
 150:             role: role.as_str().to_string(),
 151:             participant: participant.to_string(),
 152:             attempt,
 153:             unfinished: (!finished).then_some("the job is running"),
 154:         }
 155:     }
 156: }
