 158: /// `blit jobs log <job-id|file>` (jl-2): a job run on this machine — every
 159: /// log kept for it here — or the one log file named. A name that is a file
 160: /// is read as one; any other is a job ID.
 161: fn write_local_log(
 162:     out: &mut impl Write,
 163:     target: &str,
 164:     role: Option<Role>,
 165:     json: bool,
 166: ) -> Result<()> {
 167:     let file = Path::new(target);
 168:     let logs: Vec<(PathBuf, Heading)> = if file.is_file() {
 169:         if role.is_some() {
 170:             eyre::bail!("--role picks among a job's logs; {target} is one log file");
 171:         }
 172:         if json {
 173:             // Any file's lines as stored, a damaged log's too.
 174:             write_json_log(out, open_stored(file)?)?;
 175:             out.flush()?;
 176:             return Ok(());
 177:         }
 178:         let start =
 179:             job_log::read_start(file).with_context(|| format!("reading {}", file.display()))?;
 180:         let heading = Heading::from_disk(
 181:             start.role,
 182:             &start.participant,
 183:             start.attempt,
 184:             !job_log::is_partial(file),
 185:         );
 186:         vec![(file.to_path_buf(), heading)]
 187:     } else if job_log::valid_id(target) {
 188:         let dir = crate::run_log::logs_dir(&blit_core::config::config_dir()?);
 189:         let found = job_log::logs_for_run(&dir, target, role)?;
 190:         if found.is_empty() {
 191:             eyre::bail!(
 192:                 "no log for job {target} on this machine (`blit jobs list` shows the \
 193:                  jobs kept here; for a daemon's job, name its host first: \
 194:                  `blit jobs log <host> <job-id>`)"
 195:             );
 196:         }
 197:         found
 198:             .into_iter()
 199:             .map(|log| {
 200:                 let heading = Heading::from_disk(
 201:                     log.key.role(),
 202:                     log.key.participant(),
 203:                     log.key.attempt(),
 204:                     log.finished,
 205:                 );
 206:                 (log.path, heading)
 207:             })
 208:             .collect()
 209:     } else {
 210:         eyre::bail!("{target} is not a log file or a job ID");
 211:     };
 212:     for (index, (path, heading)) in logs.iter().enumerate() {
 213:         let lines = open_stored(path)?;
 214:         if json {
 215:             write_json_log(out, lines)?;
 216:         } else {
 217:             if index > 0 {
 218:                 writeln!(out)?;
 219:             }
 220:             write_text_log(out, heading, lines)?;
 221:         }
 222:     }
 223:     out.flush()?;
 224:     Ok(())
 225: }
