 227: /// A log file's lines as stored.
 228: fn open_stored(path: &Path) -> Result<Box<dyn BufRead + Send>> {
 229:     std::fs::File::open(path)
 230:         .and_then(job_log::decode)
 231:         .with_context(|| format!("reading {}", path.display()))
 232: }
 233: 
 234: fn write_text_log(
 235:     out: &mut impl Write,
 236:     heading: &Heading,
 237:     lines: Box<dyn BufRead + Send>,
 238: ) -> Result<()> {
 239:     let unfinished = heading
 240:         .unfinished
 241:         .map(|why| format!(" — not finished: {why}"))
 242:         .unwrap_or_default();
 243:     writeln!(
 244:         out,
 245:         "== {} log from machine {} (attempt {}){unfinished} ==",
 246:         heading.role, heading.participant, heading.attempt
 247:     )?;
 248:     for line in LogLines::new(lines) {
 249:         match line? {
 250:             LogLine::Event(event) => writeln!(out, "{}", job_log::text_line(&event))?,
 251:             LogLine::Unreadable { line, torn: true } => {
 252:                 writeln!(out, "(line {line} was cut short)")?
 253:             }
 254:             LogLine::Unreadable { line, torn: false } => {
 255:                 writeln!(out, "(line {line} is not a log event)")?
 256:             }
 257:         }
 258:     }
 259:     Ok(())
 260: }
