 262: /// The log's lines as stored. A log cut short mid-line still ends with a
 263: /// newline, so the next log starts on a line of its own.
 264: fn write_json_log(out: &mut impl Write, mut lines: Box<dyn BufRead + Send>) -> Result<()> {
 265:     let mut line = Vec::new();
 266:     loop {
 267:         line.clear();
 268:         if lines.read_until(b'\n', &mut line)? == 0 {
 269:             return Ok(());
 270:         }
 271:         out.write_all(&line)?;
 272:         if !line.ends_with(b"\n") {
 273:             out.write_all(b"\n")?;
 274:         }
 275:     }
 276: }
