 112: struct DelegationContext {
 113:     _ctx: TestContext,
 114:     _second: Option<SpawnedDaemon>,
 115:     src_port: u16,
 116:     dst_port: u16,
 117:     cli_bin: PathBuf,
 118:     config_dir: PathBuf,
 119:     module_src_dir: Option<PathBuf>,
 120:     module_dst_dir: PathBuf,
 121: }
 122: 
 123: impl DelegationContext {
 124:     /// Real source daemon + delegation-enabled destination daemon.
 125:     fn with_real_source() -> Self {
 126:         // The context's own daemon is the plain source; the
 127:         // destination (whose delegation gate + job table are under
 128:         // test) is the second daemon.
 129:         let ctx = TestContext::new();
 130:         let dst = ctx.spawn_second_daemon(
 131:             "daemon_dst",
 132:             &DaemonOptions {
 133:                 delegation: true,
 134:                 ..Default::default()
 135:             },
 136:         );
 137: 
 138:         Self {
 139:             src_port: ctx.daemon_port,
 140:             dst_port: dst.port,
 141:             cli_bin: ctx.cli_bin.clone(),
 142:             config_dir: ctx.config_dir.clone(),
 143:             module_src_dir: Some(ctx.module_dir.clone()),
 144:             module_dst_dir: dst.module_dir.clone(),
 145:             _ctx: ctx,
 146:             _second: Some(dst),
 147:         }
 148:     }
 149: 
 150:     /// Fake stalling source + delegation-enabled destination daemon.
 151:     /// The fake's port is owned by the caller's `FakeServerGuard`.
 152:     fn with_stalling_source(fake_port: u16) -> Self {
 153:         let ctx = TestContext::builder().delegation(true).build();
 154: 
 155:         Self {
 156:             src_port: fake_port,
 157:             dst_port: ctx.daemon_port,
 158:             cli_bin: ctx.cli_bin.clone(),
 159:             config_dir: ctx.config_dir.clone(),
 160:             module_src_dir: None,
 161:             module_dst_dir: ctx.module_dir.clone(),
 162:             _ctx: ctx,
 163:             _second: None,
 164:         }
 165:     }
