 189: /// Run a detached delegated copy and return the transfer_id parsed
 190: /// from the `--json` detach output ({"outcome":"detached", ...}).
 191: fn detach_copy(ctx: &DelegationContext) -> String {
 192:     let src = ctx.source_remote();
 193:     let dst = ctx.dest_remote();
 194:     let output = ctx.run_blit(&["copy", &src, &dst, "--detach", "--json"]);
 195:     assert!(
 196:         output.status.success(),
 197:         "detached copy must succeed\nstdout:\n{}\nstderr:\n{}",
 198:         String::from_utf8_lossy(&output.stdout),
 199:         String::from_utf8_lossy(&output.stderr)
 200:     );
 201:     let json: serde_json::Value = serde_json::from_slice(&output.stdout).unwrap_or_else(|err| {
 202:         panic!(
 203:             "--detach --json must emit valid JSON ({err})\nstdout:\n{}",
 204:             String::from_utf8_lossy(&output.stdout)
 205:         )
 206:     });
 207:     assert_eq!(
 208:         json.get("outcome").and_then(|o| o.as_str()),
 209:         Some("detached"),
 210:         "detach JSON must carry outcome=detached, got: {json}"
 211:     );
 212:     let transfer_id = json
 213:         .get("transfer_id")
 214:         .and_then(|t| t.as_str())
 215:         .expect("detach JSON must carry transfer_id");
 216:     assert!(!transfer_id.is_empty(), "transfer_id must not be empty");
 217:     transfer_id.to_string()
 218: }
